const key = (msg.topic || "").split("/").pop();
const numericMetrics = [
    "battery_level",
    "electric_range",
    "fuel_level",
    "odometer",
    "charging_power",
    "time_to_target_min",
    "target_battery_level"
];

if (key === "lock_status") {
    const state = String(msg.payload).trim().toUpperCase();
    if (state === "LOCKED") {
        msg.topic = "mcmdhome/volvo/status";
        msg.payload = "Secured";
        return [null, msg];
    }
    if (state === "UNLOCKED") {
        msg.topic = "mcmdhome/volvo/status";
        msg.payload = "Unsecured";
        return [null, msg];
    }
    return null;
}

if (key === "any_open") {
    const value = String(msg.payload).trim().toLowerCase();
    if (value !== "true" && value !== "false") return null;
    msg.measurement = "mcmdhome/volvo/any_open";
    msg.topic = msg.measurement;
    msg.payload = value === "true";
    return [msg, null];
}

if (!numericMetrics.includes(key) || String(msg.payload).trim() === "") return null;
const value = Number(msg.payload);
if (!Number.isFinite(value)) return null;
const measurement = key === "electric_range" ? "range" : key;
msg.measurement = `mcmdhome/volvo/${measurement}`;
msg.topic = msg.measurement;
msg.payload = value;
return [msg, null];

const data = (msg.payload && msg.payload.data) || {};
const coordinates = (data.geometry && data.geometry.coordinates) || [];
const properties = data.properties || {};
const fields = {};

if (Number.isFinite(Number(coordinates[0]))) fields.longitude = Number(coordinates[0]);
if (Number.isFinite(Number(coordinates[1]))) fields.latitude = Number(coordinates[1]);
if (Number.isFinite(Number(properties.heading))) fields.heading = Number(properties.heading);
if (Object.keys(fields).length === 0) return null;

msg.measurement = "mcmdhome/gps/volvo";
msg.payload = fields;
return msg;
